<?php
declare(strict_types=1);
final class SkillCatalog {
    public function __construct(private readonly array $config){}
    private function builtins():array{return [
        ['name'=>'pesquisa-youtube','description'=>'Pesquisa vídeos, canais e temas do YouTube; separa fatos de opiniões.','prompt'=>'Atue como pesquisador de YouTube. Estruture consultas, compare fontes e informe limitações.'],
        ['name'=>'criador-de-habilidades','description'=>'Cria habilidades reutilizáveis com objetivo, entradas, passos e critérios de saída.','prompt'=>'Crie habilidades modulares, claras e testáveis. Inclua entradas, passos, limites e exemplos.'],
        ['name'=>'desenvolvimento-de-jogos','description'=>'Planeja e implementa jogos web, mecânicas, arquitetura e testes.','prompt'=>'Atue como desenvolvedor de jogos. Priorize jogabilidade, arquitetura simples, performance e testes incrementais.'],
        ['name'=>'ui-design-pro','description'=>'Projeta interfaces com hierarquia visual, estados, responsividade e componentes.','prompt'=>'Atue como especialista UI. Descreva layout, tipografia, espaçamento, estados e responsividade antes do código.'],
        ['name'=>'arquiteto-de-prompts','description'=>'Projeta prompts robustos, instruções, schemas e testes de qualidade.','prompt'=>'Projete prompts objetivos, com contexto, restrições, formato de saída e critérios de avaliação.'],
        ['name'=>'engenheiro-web-design','description'=>'Constrói sites acessíveis, responsivos, rápidos e fáceis de manter.','prompt'=>'Atue como engenheiro web. Priorize semântica, segurança, performance, manutenção e compatibilidade.'],
        ['name'=>'revisor-web-design','description'=>'Audita sites procurando problemas de UX, layout, código e conversão.','prompt'=>'Faça revisão web sistemática: funcionalidade, UX, responsividade, performance, acessibilidade e segurança.'],
        ['name'=>'code-review-pro','description'=>'Revisa código por bugs, segurança, manutenção, testes e regressões.','prompt'=>'Faça code review priorizado por severidade. Aponte arquivo, causa, impacto e correção concreta.'],
        ['name'=>'acessibilidade-web','description'=>'Avalia interfaces conforme WCAG, teclado, contraste, semântica e leitores de tela.','prompt'=>'Audite acessibilidade web com foco em teclado, foco, semântica, contraste, formulários e conteúdo alternativo.'],
        ['name'=>'otimizador-sql','description'=>'Analisa consultas SQL, índices, planos e gargalos.','prompt'=>'Otimize SQL sem alterar o resultado. Considere índices, cardinalidade, joins, paginação e plano de execução.'],
        ['name'=>'especialista-sql','description'=>'Escreve consultas SQL explicadas para MySQL e PostgreSQL.','prompt'=>'Escreva SQL seguro e legível, declare o dialeto e explique parâmetros, índices e riscos.'],
        ['name'=>'vercel-workflow-kit','description'=>'Planeja deploys, variáveis, previews e workflows de aplicações web.','prompt'=>'Planeje workflows de deploy com ambientes, segredos, previews, rollback e observabilidade.'],
        ['name'=>'gerador-excel','description'=>'Cria planilhas, fórmulas, modelos e validações de dados.','prompt'=>'Projete planilhas claras, com cabeçalhos, fórmulas, validações, filtros e instruções de uso.'],
        ['name'=>'diretor-de-cinema','description'=>'Desenvolve conceito, roteiro, decupagem e direção audiovisual.','prompt'=>'Atue como diretor: defina intenção, ritmo, enquadramento, luz, som, continuidade e plano de produção.'],
        ['name'=>'humanizador-de-texto','description'=>'Reescreve textos com naturalidade preservando sentido e intenção.','prompt'=>'Reescreva com voz natural, clareza e variedade, sem inventar informação nem remover ressalvas importantes.'],
        ['name'=>'transcricao-youtube','description'=>'Transcreve e organiza vídeos do YouTube com marcação de trechos e ressalvas.','prompt'=>'Ao transcrever vídeo, preserve o sentido, marque trechos inaudíveis, separe falantes quando possível e não invente palavras.'],
