        ['name'=>'producao-video-html','description'=>'Cria roteiros e páginas HTML para vídeos, apresentações e storyboards interativos.','prompt'=>'Produza HTML semântico e responsivo para vídeo ou storyboard, com controles, acessibilidade e fallback textual.'],
