    private function dir():string{$dir=$this->config['storage'].DIRECTORY_SEPARATOR.'skills';if(!is_dir($dir))@mkdir($dir,0775,true);return $dir;}
    public function list():array{$out=[];$files=[];foreach(glob($this->dir().DIRECTORY_SEPARATOR.'*.json')?:[] as $f){$x=json_decode((string)file_get_contents($f),true);if(is_array($x)&&isset($x['name']))$files[$x['name']]=$x;}foreach($this->builtins() as $x)$out[]=$files[$x['name']]??array_merge($x,['enabled'=>false,'builtin'=>true]);foreach($files as $name=>$x)if(!array_filter($this->builtins(),static fn($b)=>$b['name']===$name))$out[]=$x;return $out;}
    public function install(array $x):array{$name=trim((string)($x['name']??''));$prompt=trim((string)($x['prompt']??''));if(!preg_match('/^[a-zA-Z0-9._-]{2,80}$/',$name)||$prompt==='')throw new InvalidArgumentException('Habilidade inválida.');$x=['name'=>$name,'description'=>trim((string)($x['description']??'')),'prompt'=>$prompt,'enabled'=>false,'builtin'=>false];file_put_contents($this->dir().DIRECTORY_SEPARATOR.$name.'.json',json_encode($x,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));return $x;}
    public function seed():array{$items=[];foreach($this->builtins() as $x){$x['enabled']=false;$x['builtin']=true;file_put_contents($this->dir().DIRECTORY_SEPARATOR.$x['name'].'.json',json_encode($x,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));$items[]=$x['name'];}return $items;}
    public function importZip(string $zipPath):array{
        if(!is_file($zipPath)||filesize($zipPath)>15*1024*1024)throw new InvalidArgumentException('ZIP inválido ou maior que 15 MB.');
        $tmp=$this->config['storage'].DIRECTORY_SEPARATOR.'.skill-import-'.bin2hex(random_bytes(8));if(!mkdir($tmp,0700,true))throw new RuntimeException('Não foi possível preparar a importação.');
        try{$entries=[];
            if(class_exists('ZipArchive')){$zip=new ZipArchive();if($zip->open($zipPath)!==true)throw new InvalidArgumentException('Não foi possível ler o ZIP.');for($i=0;$i<$zip->numFiles;$i++)$entries[]=(string)(($zip->statIndex($i)['name']??''));foreach($entries as $entry)$this->validateZipEntry($entry);if(!$zip->extractTo($tmp))throw new InvalidArgumentException('Falha ao extrair o ZIP.');$zip->close();}
            elseif(function_exists('exec')&&shell_exec('command -v unzip 2>/dev/null')){$cmd='unzip -Z1 -- '.escapeshellarg($zipPath);exec($cmd,$entries,$status);if($status!==0||!$entries)throw new InvalidArgumentException('Não foi possível ler o ZIP.');foreach($entries as $entry)$this->validateZipEntry((string)$entry);exec('unzip -qq -o -- '.escapeshellarg($zipPath).' -d '.escapeshellarg($tmp),$out,$status);if($status!==0)throw new InvalidArgumentException('Falha ao extrair o ZIP.');}
            else throw new RuntimeException('Ative a extensão ZipArchive do PHP para importar ZIP no Windows.');
            $candidates=array_merge(glob($tmp.DIRECTORY_SEPARATOR.'SKILL.md')?:[],glob($tmp.DIRECTORY_SEPARATOR.'*'.DIRECTORY_SEPARATOR.'SKILL.md')?:[]);if(count($candidates)!==1)throw new InvalidArgumentException('O ZIP deve conter exatamente um SKILL.md na raiz ou em uma pasta.');$skillFile=$candidates[0];$raw=(string)file_get_contents($skillFile);if(strlen($raw)>500*1024)throw new InvalidArgumentException('SKILL.md maior que 500 KB.');$name='';$description='';$body=$raw;
            if(preg_match('/\A---\s*\R(.*?)\R---\s*\R/s',$raw,$m)){foreach(preg_split('/\R/',trim($m[1])) as $line){if(preg_match('/^name:\s*["\']?([^"\']+?)["\']?\s*$/',$line,$mm))$name=trim($mm[1]);if(preg_match('/^description:\s*["\']?(.*?)["\']?\s*$/',$line,$mm))$description=trim($mm[1]);}$body=substr($raw,strlen($m[0]));}
            $name=strtolower(trim($name));if(!preg_match('/^[a-z0-9][a-z0-9._-]{1,79}$/',$name))throw new InvalidArgumentException('SKILL.md sem name válido no frontmatter.');if($description==='')$description='Habilidade importada de SKILL.md.';$root=dirname($skillFile);$dest=$this->dir().DIRECTORY_SEPARATOR.$name;if(is_dir($dest))$this->removeTree($dest);if(!mkdir($dest,0700,true))throw new RuntimeException('Não foi possível criar a habilidade.');$refs=[];$iterator=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS));foreach($iterator as $file){if(!$file->isFile())continue;$rel=str_replace('\\','/',substr($file->getPathname(),strlen($root)+1));if($rel==='SKILL.md'||!preg_match('/\.(md|markdown|txt|json)$/i',$rel)||$file->getSize()>2*1024*1024)continue;$target=$dest.DIRECTORY_SEPARATOR.str_replace('/',DIRECTORY_SEPARATOR,$rel);if(!is_dir(dirname($target)))mkdir(dirname($target),0700,true);copy($file->getPathname(),$target);if(str_starts_with($rel,'references/'))$refs[]=$rel;}$prompt='# '.$name."\n\n".$body;if($refs)$prompt.="\n\nReferências disponíveis no pacote: ".implode(', ',$refs);$x=['name'=>$name,'description'=>$description,'prompt'=>trim($prompt),'enabled'=>false,'builtin'=>false,'source_format'=>'SKILL.md','package_dir'=>'storage/skills/'.$name,'references'=>$refs];file_put_contents($this->dir().DIRECTORY_SEPARATOR.$name.'.json',json_encode($x,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));return $x;
        }finally{$this->removeTree($tmp);}
    }
    private function validateZipEntry(string $entry):void{$entry=str_replace('\\','/',trim($entry));$parts=explode('/',$entry);if($entry===''||str_starts_with($entry,'/')||preg_match('/^[A-Za-z]:/',$entry)||in_array('..',$parts,true)||preg_match('/[\x00-\x1F]/',$entry)||strlen($entry)>240)throw new InvalidArgumentException('ZIP rejeitado: caminho inválido.');}
    private function removeTree(string $dir):void{if(!is_dir($dir))return;$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST);foreach($it as $f){$f->isDir()?@rmdir($f->getPathname()):@unlink($f->getPathname());}@rmdir($dir);}
    public function setEnabled(string $name,bool $enabled):array{$all=$this->list();foreach($all as $x)if($x['name']===$name){$x['enabled']=$enabled;file_put_contents($this->dir().DIRECTORY_SEPARATOR.$name.'.json',json_encode($x,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));return $x;}throw new RuntimeException('Habilidade não encontrada.');}
    public function prompt():string{$rows=[];foreach(array_filter($this->list(),static fn($x)=>($x['enabled']??false)===true) as $x){$rows[]='- '.$x['name'].': '.$x['description']." Instrução: ".(function()use($x){$limit=(($x['source_format']??'')==='SKILL.md'?6000:900);$text=(string)($x['prompt']??'');return function_exists('mb_substr')?mb_substr($text,0,$limit):substr($text,0,$limit);})();if(count($rows)>=8)break;}return $rows?"\nHabilidades ativadas:\n".implode("\n",$rows):'';}
}
